import { Component, inject } from '@angular/core';
import { PieService } from '../../services/pie.service';
import { NgFor, NgIf, AsyncPipe } from '@angular/common';
import { MatButtonModule } from '@angular/material/button';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { FormsModule } from '@angular/forms';
import { ReplaySubject, takeUntil } from 'rxjs';
import { ContactForm } from 'src/app/models/contact-form';
import { ContactService } from 'src/app/services/contact.service';

@Component({
  standalone: true,
  imports: [
    NgFor,
    NgIf,
    AsyncPipe,
    MatButtonModule,
    FormsModule,
    MatProgressSpinnerModule,
  ],
  selector: 'app-customize-view',
  templateUrl: './customize-view.component.html',
  styleUrls: ['./customize-view.component.css']
})
export class CustomizeViewComponent {
  selectedPie$ = this.pieService.selectedPie$;
  constructor(private readonly pieService: PieService,){}
  readonly contactService = inject(ContactService);
  destroyed$ = new ReplaySubject<void>(1);

  model: ContactForm = {
    phone: '',
    comment: '',
  };
  submitted = false;
  loading = false;

  submitForm(model: ContactForm) {
    this.submitted = true;
    this.loading = true;

    this.contactService.submitContactForm(model).pipe(
      takeUntil(this.destroyed$)
    ).subscribe(() => {
      this.loading = false;
    })
  }

  clearForm() {
    this.submitted = false;
    this.model = {
      phone: '',
      comment: '',
    }
  }

  ngOnDestroy(): void {
    this.destroyed$.next();
    this.destroyed$.complete();
  }
}
<div class="detail" *ngIf="selectedPie$ | async as selectedPie">
  <h3>Customized {{ selectedPie.title }}</h3>
  <p>Tell us how we can customize your order. Additional ingredients will result in an extra charge.</p>
  <div class="image-wrapper">
    <img [src]="selectedPie.image" [alt]="selectedPie.title" />
    <div *ngIf="!submitted; else formSubmitted" class="form-wrapper">
      <fieldset>
        <form #contactForm="ngForm">
          <div class="form-group">
            <label for="phone">Phone *</label>
            <input
              type="tel"
              id="phone"
              name="phone"
              [(ngModel)]="model.phone"
              value=""
            />
          </div>
          <div class="form-group">
            <label for="comment">Instructions *</label>
            <textarea
              id="comment"
              name="comment"
              [(ngModel)]="model.comment"
              required
              #comment="ngModel"
            ></textarea>
            <div
              *ngIf="comment.invalid && comment.touched"
              class="alert alert-danger"
            >Instructions are required
            </div>
          </div>

          <p class="price">Price: <span>{{ selectedPie.price }}</span></p>

          <button
            [disabled]="contactForm.invalid"
            mat-raised-button
            type="submit"
            name="submit"
            id="submit"
            (click)="submitForm(model)"
          >Request Custom Pie
          </button>
        </form>
      </fieldset>
    </div>
  </div>
</div>
<ng-template #formSubmitted>
  <div
    class="form-wrapper"
    *ngIf="!loading; else submitting"
  >
    <h3>Thank You for Your Order</h3>
    <p>It may take up to 24 hours for someone to respond.</p>
    <button mat-raised-button (click)="clearForm()">Order Another</button>
  </div>
</ng-template>

<ng-template #submitting>
  <div
  class="form-wrapper-spinner"
>
  <mat-spinner></mat-spinner>
</div>
</ng-template>
